"""Offline evidence browser. No network requests, external assets or executable input."""
from __future__ import annotations

import base64
import hashlib
from html import escape
import json

CSS = '''
:root{color-scheme:light;--ink:#192d30;--muted:#4c6367;--paper:#f3f5f1;--line:#c7d2cf;--accent:#155a51;--soft:#e3eee8}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,sans-serif}a{color:var(--accent);text-underline-offset:3px}button,input,select{font:inherit}button,a,input,select,summary{touch-action:manipulation}:focus-visible{outline:3px solid #a24e05;outline-offset:4px}.skip{position:absolute;top:-90px;left:1rem;background:white;padding:.6rem;z-index:5}.skip:focus{top:1rem}header,main,footer{max-width:1440px;margin:auto;padding:2rem 3rem}header{border-bottom:1px solid var(--line)}.brand{font-weight:750;letter-spacing:.02em;display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap}.label{font-size:.76rem;text-transform:uppercase;letter-spacing:.13em;color:var(--muted);font-weight:750}h1{font-size:clamp(1.8rem,3vw,2.6rem);line-height:1.12;max-width:900px;letter-spacing:-.035em;margin:1rem 0 .6rem}h2{font-size:1.5rem;line-height:1.2}h3{font-size:1.12rem}p{max-width:85ch;overflow-wrap:anywhere}.muted{color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem;margin:1.8rem 0 0}.metric{border-left:2px solid var(--line);padding-left:1rem}.metric strong{display:block;font-size:1.7rem;font-variant-numeric:tabular-nums}.toolbar{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:1rem;align-items:end;background:white;border:1px solid var(--line);padding:1rem;margin:1.5rem 0}.toolbar label{display:grid;gap:.35rem;font-size:.85rem;font-weight:650}input,select{width:100%;min-width:0;border:1px solid #78918b;border-radius:4px;padding:.65rem;background:white;color:var(--ink)}button{cursor:pointer;border:1px solid var(--accent);border-radius:4px;background:var(--accent);color:white;padding:.65rem 1rem;font-weight:650;min-height:44px}button.secondary{background:white;color:var(--accent)}.layout{display:grid;grid-template-columns:minmax(270px,1fr) minmax(0,2fr);gap:1.5rem;align-items:start}.study{background:white;border:1px solid var(--line);border-radius:6px;margin:0 0 1rem;padding:1.2rem}.study h3{overflow-wrap:anywhere;margin:.5rem 0}.study.selected{border:2px solid var(--accent);padding:calc(1.2rem - 1px)}.study p{margin:.5rem 0}.study .actions{display:flex;align-items:center;gap:1rem;flex-wrap:wrap;margin-top:1rem}.badge{overflow-wrap:anywhere;max-width:100%;font-size:.76rem;display:inline-block;border:1px solid #a2b8af;border-radius:3px;background:var(--soft);padding:.2rem .5rem;font-weight:700}.details{min-width:0;background:white;border:1px solid var(--line);border-radius:6px;padding:1.5rem}dl{display:grid;grid-template-columns:minmax(100px,1fr) 2fr;gap:.5rem 1rem}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}.scroll{overflow:auto;max-width:100%;margin:1rem 0}table{width:100%;border-collapse:collapse;font-size:.87rem;text-align:left}caption{text-align:left;color:var(--muted);padding:.6rem 0}th,td{border-bottom:1px solid var(--line);padding:.65rem .7rem;vertical-align:top}thead th{background:var(--paper)}td{font-variant-numeric:tabular-nums}tbody th{overflow-wrap:anywhere;max-width:20rem}code{font-size:.86em;overflow-wrap:anywhere}summary{cursor:pointer;font-weight:650;padding:.5rem 0}.chart{width:100%;height:auto;display:block;border:1px solid var(--line);background:var(--paper);margin-top:1rem}.note{border-left:3px solid var(--accent);padding:.1rem 1rem;background:var(--soft)}.section{margin-top:3rem;border-top:1px solid var(--line);padding-top:1rem}.empty{padding:2rem;border:1px dashed var(--line)}[hidden]{display:none!important}footer{font-size:.88rem;color:var(--muted)}.js-only{display:none}.js .js-only{display:block}.js .toolbar{display:grid}
@media(max-width:900px){header,main,footer{padding:1.5rem}.layout{grid-template-columns:1fr}.toolbar{grid-template-columns:1fr 1fr}.metrics{grid-template-columns:1fr 1fr}.study-list{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.study{margin:0}.details{padding:1rem}}@media(max-width:540px){header,main,footer{padding:1rem}.toolbar,.study-list{grid-template-columns:1fr}.metrics{gap:1rem .5rem}.metric strong{font-size:1.45rem}dl{grid-template-columns:1fr;gap:.15rem}dd{margin-bottom:.6rem}.study-list{max-height:70vh;overflow:auto;padding:4px}.details h2{overflow-wrap:anywhere}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}@media print{.toolbar,.js-only,button,.skip{display:none!important}.layout,.study-list{display:block;max-height:none}.study{break-inside:avoid;margin-bottom:1rem}header,main,footer{padding:1rem}body{background:white}}
'''

SCRIPT = r'''
'use strict';
const data=JSON.parse(document.getElementById('browser-data').textContent);
document.documentElement.classList.add('js');
const labels={uniform_random:'Uniform random',grid_search:'Grid search',coordinate_refinement:'Coordinate refinement',coordinate_fixed_step:'Fixed-step coordinate',CANDIDATE_LOWER:'Candidate lower',BASELINE_LOWER:'Baseline lower',TIE:'Tie',INCONCLUSIVE:'Inconclusive',DETERMINISTIC_NO_SAMPLING_INTERVAL:'Deterministic; no sampling interval',INSUFFICIENT_PAIRS:'Too few pairs for an interval',INELIGIBLE:'Ineligible',DESCRIPTIVE:'Descriptive seed resampling'};
const label=value=>labels[value]||String(value);
const $=id=>document.getElementById(id);
const number=v=>v===null||v===undefined?'Not available':typeof v==='number'?Number(v.toPrecision(10)).toString():String(v);
const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);return e};
function table(parent,caption,headings,rows){const box=node('div');box.className='scroll';box.tabIndex=0;box.setAttribute('role','region');box.setAttribute('aria-label',caption);const t=node('table');t.append(node('caption',caption));const head=node('thead'),tr=node('tr');for(const h of headings){const th=node('th',h);th.scope='col';tr.append(th)}head.append(tr);t.append(head);const body=node('tbody');for(const values of rows){const tr=node('tr');values.forEach((v,i)=>{const cell=node(i===0?'th':'td');if(i===0)cell.scope='row';if(v instanceof Node)cell.append(v);else cell.textContent=number(v);tr.append(cell)});body.append(tr)}t.append(body);box.append(t);parent.append(box)}
let selected=null;
function filter(){const query=$('search').value.toLowerCase().trim(),objective=$('objective').value,verdict=$('verdict').value;let visible=0;const cards=[...document.querySelectorAll('.study')];const sort=$('sort').value;cards.sort((a,b)=>sort==='cost'?Number(b.dataset.cost)-Number(a.dataset.cost):Number(a.dataset.order)-Number(b.dataset.order));for(const card of cards){$('study-list').append(card);card.hidden=!(card.dataset.search.includes(query)&&(!objective||card.dataset.objective===objective)&&(!verdict||card.dataset.verdict===verdict));if(!card.hidden)visible++}$('result-count').textContent=`${visible} of ${cards.length} studies shown. Campaign totals always include all studies.`;$('empty').hidden=visible!==0;if(!cards.some(c=>!c.hidden&&c.dataset.id===selected)){const first=cards.find(c=>!c.hidden);if(first)showStudy(first.dataset.id,false);else{$('study-detail').replaceChildren(node('h2','No matching study'),node('p','Reset or change the filters to inspect study evidence.'));selected=null}}}
for(const id of ['search','objective','verdict','sort'])$(id).addEventListener(id==='search'?'input':'change',filter);
$('reset').addEventListener('click',()=>{for(const id of ['search','objective','verdict','sort'])$(id).value='';filter();$('search').focus()});
function showStudy(id,focus=true,trialId=null){selected=id;const item=data.studies.find(s=>s.id===id);for(const card of document.querySelectorAll('.study')){card.classList.toggle('selected',card.dataset.id===id);card.querySelector('button').setAttribute('aria-pressed',String(card.dataset.id===id))}const detail=$('study-detail');detail.replaceChildren();const heading=node('h2',item.id);heading.tabIndex=-1;detail.append(node('div','Study evidence'),heading,node('p',item.question));const note=node('p',`${label(item.summary.verdict)} · ${item.summary.hypothesis_relation} · Unreviewed`);note.className='badge';detail.append(note);if(item.summary.inconclusive_reasons.length){const ul=node('ul');item.summary.inconclusive_reasons.forEach(r=>ul.append(node('li',r)));detail.append(ul)}const dl=node('dl');for(const [k,v] of [['Objective',item.objective],['Baseline',label(item.baseline)],['Candidate',label(item.candidate)],['Charged / reserved',`${item.summary.charged_evaluations} / ${item.summary.reserved_evaluations}`],['Recorded evaluations',item.summary.recorded_evaluations],['Study identity',item.summary.study_digest]]){dl.append(node('dt',k),node('dd',v))}detail.append(dl);const link=node('a','Open full study report and provenance');link.href=`studies/${id}/report.html`;detail.append(link);const u=item.summary.uncertainty;if(u){detail.append(node('h3','Paired seed uncertainty'));detail.append(node('p',`${label(u.status)} · ${u.n_pairs} original confirmation pairs`));detail.append(node('p',`Median paired candidate − baseline: ${number(u.median_difference)}. Descriptive interval: ${u.interval?u.interval.map(number).join(' to '):'Not estimated'}.`));detail.append(node('p',u.interpretation))}detail.append(node('h3','Trial evidence'));const trialLabel=node('label','Choose a trial');trialLabel.htmlFor='trial-select';const select=node('select');select.id='trial-select';for(const trial of item.summary.trials){const o=node('option',`${trial.trial_id} · ${trial.status}`);o.value=trial.trial_id;select.append(o)}select.value=(item.summary.trials.find(t=>t.trial_id===trialId)||item.summary.trials.find(t=>t.phase==='confirmation'&&t.policy===item.baseline)||item.summary.trials[0]).trial_id;detail.append(trialLabel,select);const area=node('div');area.id='trial-detail';detail.append(area);select.addEventListener('change',()=>showTrial(item,select.value));showTrial(item,select.value);if(focus)heading.focus();}
function showTrial(item,id){const area=$('trial-detail');area.replaceChildren();const row=item.summary.trials.find(t=>t.trial_id===id);const fragment=new URLSearchParams({study:item.id,trial:id}).toString();history.replaceState(null,'','#'+fragment);const selection=node('a','Link to this trial selection');selection.href='#'+fragment;area.append(selection);area.append(node('p',`${row.status} · ${row.charged_evaluations} charged units · ${row.recorded_evaluations} recorded evaluations · ${row.failed_attempts} failed attempts`));const attempts=item.attempts.filter(a=>a.trial_id===id);if(!attempts.length){area.append(node('p','No attempt has been admitted. Missing outcomes are not zero scores.'));return}for(const attempt of attempts){const d=node('details');d.open=attempt===attempts[attempts.length-1];const terminal=attempt.terminal;const status=terminal?terminal.status:'RUNNING';d.append(node('summary',`Attempt ${attempt.number} · ${status} · ${attempt.charged_evaluations} charged units`));d.append(node('p',`Attempt identity: ${attempt.id}`));if(terminal)d.append(node('p',terminal.reason||'Full finite allowance completed.'));if(attempt.observations.length){const values=attempt.observations.map(o=>o.value);let best=Infinity;const bests=values.map(v=>best=Math.min(best,v));const lo=Math.min(...bests),hi=Math.max(...bests);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 640 240');svg.setAttribute('class','chart');svg.setAttribute('role','img');svg.setAttribute('aria-label',`Best objective over ${bests.length} recorded evaluations, from ${number(bests[0])} to ${number(bests[bests.length-1])}. Exact values follow.`);const line=document.createElementNS(svg.namespaceURI,'polyline');line.setAttribute('points',bests.map((v,i)=>`${40+i*570/Math.max(1,bests.length-1)},${200-(hi===lo?0.5:(v-lo)/(hi-lo))*160}`).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke','#155a51');line.setAttribute('stroke-width','2.5');svg.append(line);d.append(node('p',`Best-so-far objective over recorded evaluations 1–${bests.length}. Linear range: ${number(lo)} to ${number(hi)}; final best: ${number(bests[bests.length-1])}.`),svg);const raw=node('details');raw.append(node('summary',`Inspect all ${attempt.observations.length} points and values`));raw.addEventListener('toggle',()=>{if(raw.open&&!raw.dataset.loaded){table(raw,'Every recorded observation. Boundary duplicates consume allowance.',['Evaluation','x','y','Objective','Best so far'],attempt.observations.map((o,i)=>[i+1,o.point[0],o.point[1],o.value,bests[i]]));raw.dataset.loaded='true'}});d.append(raw)}else d.append(node('p','No durable observations. Admitted costs remain charged.'));area.append(d)}}
for(const button of document.querySelectorAll('[data-open]'))button.addEventListener('click',()=>showStudy(button.dataset.open));
const savedSelection=new URLSearchParams(location.hash.slice(1));
filter();
if(data.studies.some(s=>s.id===savedSelection.get('study')))showStudy(savedSelection.get('study'),false,savedSelection.get('trial'));
window.addEventListener('hashchange',()=>{const selection=new URLSearchParams(location.hash.slice(1));if(data.studies.some(s=>s.id===selection.get('study'))){for(const id of ['search','objective','verdict'])$(id).value='';filter();showStudy(selection.get('study'),false,selection.get('trial'))}});
'''


def render(data, summary):
    def e(value):
        return escape(str(value), quote=True)
    def label(value):
        return str(value).replace('_', ' ').capitalize()
    cards, browser_studies = [], []
    objectives = sorted({s['objective'] for s in summary['studies']})
    for index, row in enumerate(summary['studies']):
        key, result = row['id'], row['summary']
        snapshot = data['snapshots'][key]
        protocol = snapshot['study']
        groups = [g for g in result['groups'] if g['phase'] == 'confirmation']
        medians = ' · '.join(f"{label(g['policy'])}: {g['median_best']:.6g}" if g['median_best'] is not None else f"{label(g['policy'])}: missing" for g in groups)
        text = f"{key} {protocol['question']} {row['objective']} {row['baseline']} {row['candidate']} {result['verdict']}".lower()
        ablation = f'<p class="muted">Ablation of {e(row["ablation_of"])} · {e(row["factor"])}</p>' if row['ablation_of'] else ''
        cards.append(f'''<article class="study" data-id="{e(key)}" data-order="{index}" data-search="{e(text)}" data-objective="{e(row['objective'])}" data-verdict="{e(result['verdict'])}" data-cost="{result['charged_evaluations']}">
<div class="label">{e(row['objective'])}</div><h3>{e(key)}</h3><span class="badge">{e(label(result['verdict']))}</span>
<p>{e(label(row['candidate']))} vs {e(label(row['baseline']))}</p><p class="muted">Confirmation median best · {e(medians)}</p>{ablation}
<p>{result['charged_evaluations']:,} charged · {result['failed_attempts']} failed attempts</p>
<div class="actions"><button class="js-only" type="button" data-open="{e(key)}" aria-pressed="false" aria-label="Inspect {e(key)}">Inspect study</button><a href="studies/{e(key)}/report.html">Full report</a></div></article>''')
        browser_studies.append({'id': key, 'question': protocol['question'], 'objective': row['objective'],
                                'baseline': row['baseline'], 'candidate': row['candidate'], 'summary': result,
                                'attempts': snapshot['attempts']})
    ablations = []
    for row in summary['ablations']:
        u = row['uncertainty']
        value = 'Not available' if u['median_difference'] is None else format(u['median_difference'], '.10g')
        ablations.append(f'''<tr><th scope="row"><a href="studies/{e(row['variant'])}/report.html">{e(row['variant'])}</a></th>
<td><a href="studies/{e(row['reference'])}/report.html">{e(row['reference'])}</a></td><td>{e(row['factor'])}</td>
<td>{'Eligible' if row['eligible'] else 'INCONCLUSIVE'}</td><td>{e(value)}</td><td>{e(label(u['status']))}</td></tr>''')
    payload = json.dumps({'studies': browser_studies}, sort_keys=True, ensure_ascii=True, separators=(',', ':'), allow_nan=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    script_hash = base64.b64encode(hashlib.sha256(SCRIPT.encode()).digest()).decode()
    options = ''.join(f'<option value="{e(o)}">{e(o)}</option>' for o in objectives)
    state = 'All studies terminal' if summary['complete'] else 'Campaign in progress'
    limitations = ''.join(f'<li>{e(x)}</li>' for x in summary['limitations'])
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'sha256-{script_hash}'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'">
<title>Research Continuum · {e(data['frozen']['plan']['campaign_id'])}</title><style>{CSS}</style></head><body>
<a class="skip" href="#main">Skip to evidence</a><header><div class="brand"><span>RESEARCH CONTINUUM <span class="muted">/ Workbench</span></span><span class="badge">{e(state)} · Unreviewed</span></div>
<div class="label" style="margin-top:1.2rem">Frozen campaign / {e(data['frozen']['plan']['campaign_id'])}</div>
<h1>Numerical research campaign</h1><p>{e(summary['question'])}</p>
<div class="metrics"><div class="metric"><strong>{summary['study_count']}</strong>frozen studies</div><div class="metric"><strong>{summary['charged_evaluations']:,}</strong>charged evaluations</div><div class="metric"><strong>{summary['reserved_evaluations']:,}</strong>reserved evaluations</div><div class="metric"><strong>{summary['failed_attempts']}</strong>retained failed attempts</div></div></header>
<main id="main" tabindex="-1"><h2>Campaign evidence</h2><p class="muted">Compare within each frozen objective. Null results and unsuccessful attempts belong in the record.</p>
<noscript><p>Interactive controls require JavaScript. Every study and ablation remains below; full reports contain the complete ledger.</p></noscript>
<div class="toolbar js-only" role="search" aria-label="Filter study evidence"><label for="search">Find a study<input id="search" type="search" placeholder="Question, policy, or study name"></label>
<label for="objective">Objective<select id="objective"><option value="">All objectives</option>{options}</select></label>
<label for="verdict">Outcome<select id="verdict"><option value="">All outcomes</option><option value="CANDIDATE_LOWER">Candidate lower</option><option value="BASELINE_LOWER">Baseline lower</option><option value="TIE">Tie</option><option value="INCONCLUSIVE">Inconclusive</option></select></label>
<label for="sort">Order<select id="sort"><option value="">Frozen order</option><option value="cost">Highest charged cost</option></select></label>
<button class="secondary" id="reset" type="button">Reset filters</button></div>
<p id="result-count" class="js-only muted" role="status" aria-live="polite"></p>
<div class="layout"><div><p id="empty" class="empty" hidden>No studies match these filters. Reset filters to show the full inventory.</p><div class="study-list" id="study-list">{''.join(cards)}</div></div><section class="details js-only" id="study-detail" aria-label="Selected study evidence"></section></div>
<section class="section" aria-labelledby="ablations-title"><h2 id="ablations-title">What changes when one mechanism changes?</h2><p>Declared ablations retain the same objective, baseline, budgets and seeds. Negative differences favour the variant; these contrasts do not rank different objectives.</p>
<div class="scroll" tabindex="0" role="region" aria-label="Ablation contrasts"><table><caption>Original confirmation candidate outcomes, paired by frozen seed. All declared ablations are shown.</caption><thead><tr><th scope="col">Variant</th><th scope="col">Reference</th><th scope="col">Changed factor</th><th scope="col">Eligibility</th><th scope="col">Median variant − reference</th><th scope="col">Uncertainty status</th></tr></thead><tbody>{''.join(ablations)}</tbody></table></div></section>
<section class="section" aria-labelledby="limits-title"><h2 id="limits-title">Evidence has boundaries</h2><ul>{limitations}</ul><p>{summary['recorded_evaluations']:,} search evaluations are durably recorded. Charged allowance includes calls whose observations may be lost at interruption; audit replay is additional work.</p>
<details><summary>Frozen identity and portable evidence</summary><dl><dt>Execution</dt><dd><code>{e(summary['execution_id'])}</code></dd><dt>Plan SHA-256</dt><dd><code>{e(summary['plan_digest'])}</code></dd></dl><p><a href="campaign.json">Frozen campaign</a> · <a href="summary.json">All derived outcomes</a> · <a href="manifest.json">Checksummed inventory</a></p><p>Use the matching release’s campaign-verify and campaign-reproduce commands to validate and execute this evidence in a fresh directory. Checksums detect changes; they do not prove authorship or scientific validity.</p></details></section></main>
<footer>Research Continuum · Offline evidence workbench · No network requests or remote resources. Independent human and qualified review: pending.</footer>
<script id="browser-data" type="application/json">{payload}</script><script>{SCRIPT}</script></body></html>'''
